func TestCompleteContextNames(t *testing.T) {
	cfgDir := t.TempDir()
	t.Setenv("ENTIRE_CONFIG_DIR", cfgDir)
	restore := tokenstore.UseFileBackendForTesting(filepath.Join(t.TempDir(), "tokens.json"))
	t.Cleanup(restore)

	exp := time.Now().Add(time.Hour).Unix()
	// Two identities on the same core: bare host (current) + handle@host.
	if _, err := auth.RecordLoginContext(makeContextJWT(t, fmt.Sprintf(`{"iss":"https://core.example.com","handle":"alice","exp":%d}`, exp)), "", true); err != nil {
		t.Fatalf("record alice: %v", err)
	}
	if _, err := auth.RecordLoginContext(makeContextJWT(t, fmt.Sprintf(`{"iss":"https://core.example.com","handle":"bob","exp":%d}`, exp)), "", false); err != nil {
		t.Fatalf("record bob: %v", err)
	}

	got, directive := completeContextNames(nil, nil, "")
	if directive != cobra.ShellCompDirectiveNoFileComp {
		t.Fatalf("directive = %v, want NoFileComp", directive)
	}
	if len(got) != 2 {
		t.Fatalf("completions = %v, want 2", got)
	}
	// First identity is current → bare host, marked active, described by handle+core.
	if !strings.HasPrefix(got[0], "core.example.com\t") ||
		!strings.Contains(got[0], "alice") ||
		!strings.Contains(got[0], "https://core.example.com") ||
		!strings.Contains(got[0], "(active)") {
		t.Fatalf("first completion = %q, want active bare-host entry with handle/core description", got[0])
	}
	if !strings.HasPrefix(got[1], "bob@core.example.com\t") || strings.Contains(got[1], "(active)") {
		t.Fatalf("second completion = %q, want non-active bob@host entry", got[1])
	}

	// A second positional has nothing left to complete.
	if out, _ := completeContextNames(nil, []string{"core.example.com"}, ""); out != nil {
		t.Fatalf("completion past the single positional = %v, want nil", out)
	}
}

